"""Authored same-cell intersection parking probes for LVMC 11.52.130(A)(11)."""
from __future__ import annotations

import json
import math
from pathlib import Path

HERE = Path(__file__).resolve().parent
BOUNDARY_X_M = 7.0
FIFTEEN_FEET_M = 15 * .3048
PARK_STATIONS_M = {"witness_1": 25.0, "witness_2": 13.5,
                   "numeric_1_0": 13.5, "numeric_1_1": 14.172,
                   "numeric_1_2": 15.0,
                   **{f"exception_{i}_{j}": 13.5 for i in range(1,4) for j in (1,2)}}
BODY_HALF_LENGTH_M = 2.6
BODY_HALF_WIDTH_M = 1.1


def open_drive() -> str:
    path=HERE/'road.xodr'
    if not path.is_file():
        raise ValueError('Authored same-cell road is missing')
    return path.read_text()


def route(case: str) -> list[list[float]]:
    if case not in PARK_STATIONS_M:
        raise ValueError("Unknown parking probe")
    stop = PARK_STATIONS_M[case]
    shift_start = stop - 4.0 if case != "witness_1" else stop - 7.0
    shift_end = shift_start + 4.0
    points = []
    for index in range(round((stop + 70) * 20) + 1):
        x = round(-70 + index * .05, 4)
        if x <= shift_start:
            y = -1.75
        elif x >= shift_end:
            y = -5.25
        else:
            t = (x - shift_start) / 4
            y = -1.75 - 3.5 * t*t*(3-2*t)
        points.append([x, round(y, 6)])
    if points[-1][0] != stop:
        points.append([stop, -5.25])
    return points


def body(x, y):
    return ((x-2.6,y-1.1),(x-2.6,y+1.1),
            (x+2.6,y+1.1),(x+2.6,y-1.1))


def check():
    from shapely.geometry import Polygon, box
    from shapely.ops import unary_union
    road = HERE / "road.xodr"
    if not road.is_file():
        raise ValueError("Authored same-cell road is missing")
    pavement = unary_union((box(-100,-3.5,100,3.5),
                            box(-3.5,-100,3.5,100),
                            box(8,-7,35,-3.5)))
    result = {}
    for case in PARK_STATIONS_M:
        points = route(case)
        if max(math.dist(a,b) for a,b in zip(points,points[1:])) > .15:
            raise ValueError("Parking path discontinuity")
        for x,y in points:
            if not pavement.covers(Polygon(body(x,y))):
                raise ValueError("Prospective body leaves authored pavement")
        x,y = points[-1]
        if y != -5.25:
            raise ValueError("Probe did not reach parking bay")
        nearest = (x - BODY_HALF_LENGTH_M) - BOUNDARY_X_M
        relation=("boundary_unresolved" if abs(nearest-FIFTEEN_FEET_M)<.05 else
                  "within_15_ft" if nearest<FIFTEEN_FEET_M else "outside_15_ft")
        result[case] = {"stop_center_x_m":x,"nearest_body_to_intersection_m":round(nearest,4),
                        "within_15_ft_proposed":None if relation=="boundary_unresolved" else relation=="within_15_ft",
                        "sampled_relation":relation,
                        "route_points":len(points),"parking_y_m":y}
    if result["witness_1"]["within_15_ft_proposed"] or not result["witness_2"]["within_15_ft_proposed"]:
        raise ValueError("Controlled parking stations do not bracket statutory band")
    return {"passed":True,"scope":"authored route and prospective body only",
            "law_id":"LVMC-11-52-130-A11","cell_id":"C110454",
            "fifteen_feet_m":FIFTEEN_FEET_M,"intersection_entry_boundary_x_m":BOUNDARY_X_M,
            "case_results":result,"native_observed":False,"legal_verdict":None}


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("--write-routes",action="store_true")
    args=parser.parse_args()
    result=check()
    if args.write_routes:
        routes=HERE/"routes"; routes.mkdir(exist_ok=True)
        for case in PARK_STATIONS_M:
            (routes/(case+".json")).write_text(json.dumps(route(case)))
    print(json.dumps(result,sort_keys=True))

"""Unselected LVMC exception scene variants and measured fallback decisions."""
from engineering_numeric import BASE, DELTA, TRIGGERS, evaluate as evaluate_trigger

CASES = {
    'exception_1_1': ('necessary_traffic_conflict', 'absent'),
    'exception_1_2': ('necessary_traffic_conflict', 'present'),
    'exception_2_1': ('compliance_with_law', 'absent'),
    'exception_2_2': ('compliance_with_law', 'present'),
    'exception_3_1': ('police_or_device_direction', 'absent'),
    'exception_3_2': ('police_or_device_direction', 'present'),
}
CANDIDATES = ('primary', 'fallback1', 'fallback2', 'fallback3')
SCENES = {
    'necessary_traffic_conflict': {
        'control': 'cross-road actor approaches the surveyed intersection while ego brakes and parks in the same C110454 parking bay',
        'native_source': 'original synchronized ego and other-actor poses plus intersection boundary readback',
        'measured_join': 'overlap between other-actor conflict occupancy frames and ego brake frames',
        'physical_review': 'other actor visibility, collision avoidance necessity, and original route response'},
    'compliance_with_law': {
        'control': 'ego response to an authored official stop-control device at the intersection',
        'native_source': 'NRS-484B-300-1 official-device obedience text hash, device state pixels and original ego action frames',
        'measured_join': 'cited law/source hash and ego action frames',
        'physical_review': 'device applicability to the exact parking behavior and original pixels'},
    'police_or_device_direction': {
        'control': 'authored traffic-control device direction visible near the intersection parking bay',
        'native_source': 'original pixels, device identifier, direction frame and joined ego action frames',
        'measured_join': 'direction pixel frame belongs to ego response frames',
        'physical_review': 'direction intelligibility, authority, applicability and original pixels'},
}


def plan(case, candidate):
    if case not in CASES or candidate not in CANDIDATES:
        raise ValueError('Unknown exception case/candidate')
    branch, polarity = CASES[case]
    return {
        'case_suffix': case, 'candidate': candidate, 'exception_branch': branch,
        'requested_polarity': polarity, 'knobs': BASE | DELTA[candidate],
        'measured_trigger': TRIGGERS.get(candidate),
        'scene': SCENES[branch], 'physical_trigger_observed': False,
        'legal_exception_verdict': None,
    }


def parameters(case, candidate):
    return plan(case, candidate)


def controller_parameters(case, candidate):
    from controller import EngineeringKnobs
    knobs = plan(case, candidate)['knobs']
    return EngineeringKnobs(lookahead_base_m=knobs['route_lookahead_m'],
        target_speed_mps=5.5, final_brake_mps2=1.5,
        final_margin_m=knobs['parking_brake_start_m']-9.0)


def evaluate(candidate, source, expected_sha256):
    return evaluate_trigger(candidate, source, expected_sha256)

"""Unselected parking-law fallback knobs and source-bound risk decisions."""
import hashlib
import json
from pathlib import Path

CASES=("numeric_1_0","numeric_1_1","numeric_1_2")
CANDIDATES=("primary","fallback1","fallback2","fallback3")
BASE={"route_lookahead_m":6.0,"parking_brake_start_m":12.0,
      "overview_fov_deg":90.0,"rate_hz":20,"duration_s":24.0,
      "camera_ids":["overview","approach","intersection","parking"]}
DELTA={"primary":{},"fallback1":{"route_lookahead_m":3.5},
       "fallback2":{"parking_brake_start_m":17.0},
       "fallback3":{"overview_fov_deg":105.0}}
TRIGGERS={"fallback1":("max_park_route_cross_track_error_m",">",.45),
          "fallback2":("parked_endpoint_speed_m_s",">",.3),
          "fallback3":("min_parked_ego_pixel_margin_px","<",40)}


def plan(case,candidate):
    if case not in CASES or candidate not in CANDIDATES:raise ValueError("Unknown case/candidate")
    return {"case_suffix":case,"candidate":candidate,"knobs":BASE|DELTA[candidate],
            "measured_trigger":TRIGGERS.get(candidate),"physical_trigger_observed":False}


def parameters(case,candidate):
    return plan(case,candidate)


def controller_parameters(case,candidate):
    from controller import EngineeringKnobs
    knobs=plan(case,candidate)['knobs']
    return EngineeringKnobs(lookahead_base_m=knobs['route_lookahead_m'],
                            target_speed_mps=5.5,
                            final_brake_mps2=1.5,
                            final_margin_m=knobs['parking_brake_start_m']-9.0)


def evaluate(candidate,source:Path,expected_sha256:str):
    if candidate not in TRIGGERS:raise ValueError("No fallback trigger")
    if hashlib.sha256(source.read_bytes()).hexdigest()!=expected_sha256:
        raise ValueError("Original source hash differs")
    values=json.loads(source.read_text())
    if values.get("source_kind")!="native_video_metrics":
        raise ValueError("Original Native/video metrics missing")
    key,op,threshold=TRIGGERS[candidate]
    value=values.get(key)
    if type(value) not in (int,float):raise ValueError("Measured trigger value missing")
    return value>threshold if op==">" else value<threshold

"""Saved-source measurement of parked body distance to an intersection."""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

FIFTEEN_FEET_M = 4.572


def measure(source: Path, expected_sha256: str) -> dict:
    if hashlib.sha256(source.read_bytes()).hexdigest() != expected_sha256:
        raise ValueError("Original Native source hash differs")
    packet = json.loads(source.read_text())
    if packet.get("source_kind") != "native_frame_schema" or packet.get("intersection_boundary_source") != "native_map_readback":
        raise ValueError("Original Native map boundary source is absent")
    frames = packet.get("frames")
    if not isinstance(frames, list) or len(frames) != 480:
        raise ValueError("Need complete 480-frame Native source")
    boundary = packet.get("intersection_entry_boundary_x_m")
    if not isinstance(boundary, (int,float)) or not math.isfinite(boundary):
        raise ValueError("Missing surveyed intersection boundary")
    resting = []
    first_frame=frames[0].get("native_frame")
    first_time=frames[0].get("time_s")
    if type(first_frame) is not int or not isinstance(first_time,(int,float)) or not math.isfinite(first_time):
        raise ValueError("Original frame/time join differs")
    for i, row in enumerate(frames):
        if row.get("video_frame") != i or row.get("native_frame") != first_frame+i or abs(row.get("time_s",-1) - first_time-i*.05) > 1e-6:
            raise ValueError("Original frame/time join differs")
        body = row.get("body_xy_m")
        if not isinstance(body,list) or len(body)!=4 or any(not isinstance(p,list) or len(p)!=2 or any(not isinstance(v,(int,float)) or not math.isfinite(v) for v in p) for p in body):
            raise ValueError("Original body footprint absent")
        speed = row.get("speed_m_s")
        if not isinstance(speed,(int,float)) or not math.isfinite(speed) or speed<0:
            raise ValueError("Observed speed absent")
        if speed<=.05:
            resting.append((i, min(p[0] for p in body)-boundary))
    if len(resting)<40 or any(b[0]!=a[0]+1 for a,b in zip(resting,resting[1:])):
        raise ValueError("Continuous 2-second parked interval absent")
    distances=[d for _,d in resting]
    if min(distances)<0:
        raise ValueError("Parked body extends into intersection")
    relation=("boundary_unresolved" if abs(min(distances)-FIFTEEN_FEET_M)<.05 else
              "within_15_ft" if min(distances)<FIFTEEN_FEET_M else "outside_15_ft")
    return {"source_sha256":expected_sha256,"rest_frames":len(resting),
            "nearest_parked_body_distance_m":min(distances),
            "sampled_relation":relation,
            "threshold_m":FIFTEEN_FEET_M,"lawful_conflict_or_direction_exception_proven":False,
            "native_physical_observation_claimed":False,"legal_verdict":None}


if __name__=="__main__":
    import argparse
    parser=argparse.ArgumentParser();parser.add_argument("source",type=Path)
    parser.add_argument("--sha256",required=True)
    args=parser.parse_args()
    print(json.dumps(measure(args.source,args.sha256),sort_keys=True))

"""Saved exception context gate for unselected LVMC alternatives.

This tests source continuity, never statutory applicability or physical causation.
"""
import hashlib
import json
import math
from pathlib import Path
from exception_evidence import inspect as inspect_present

CITED_DEVICE_LAW_ID='NRS-484B-300-1'
CITED_DEVICE_LAW_SHA256='0083bdf940bab787cf1d1cf789a93d1edf516df1df6de3b3e91cca237c6bbba8'

BRANCHES = {
    'exception_1_1': ('necessary_traffic_conflict', 'absent'),
    'exception_1_2': ('necessary_traffic_conflict', 'present'),
    'exception_2_1': ('compliance_with_law', 'absent'),
    'exception_2_2': ('compliance_with_law', 'present'),
    'exception_3_1': ('police_or_device_direction', 'absent'),
    'exception_3_2': ('police_or_device_direction', 'present'),
}


def inspect_case(path: Path, suffix: str, original_frames: list[int]):
    path = Path(path)
    if not path.is_file():
        raise ValueError('Missing required source: exception_context.json')
    if suffix not in BRANCHES:
        raise ValueError('Unknown exception case')
    digest = hashlib.sha256(path.read_bytes()).hexdigest()
    packet = json.loads(path.read_text())
    branch, polarity = BRANCHES[suffix]
    if packet.get('source_kind') != 'native_context_schema' or packet.get('branch') != branch:
        raise ValueError('Exception case source identity differs')
    if packet.get('requested_polarity') != polarity:
        raise ValueError('Exception polarity differs')
    if packet.get('original_frames') != original_frames:
        raise ValueError('Exception context is not joined to all original frames')
    if polarity == 'present':
        if branch == 'compliance_with_law' and (packet.get('cited_law_id') != CITED_DEVICE_LAW_ID or
                packet.get('cited_law_text_sha256') != CITED_DEVICE_LAW_SHA256):
            raise ValueError('Cited law differs from frozen NRS 484B.300(1) source')
        if branch == 'compliance_with_law':
            action_source=path.parent/'device_action_history.jsonl'
            if not action_source.is_file():
                raise ValueError('Missing required source: device_action_history.jsonl')
            action_rows=[json.loads(line) for line in action_source.read_text().splitlines() if line.strip()]
            if len(action_rows)!=len(original_frames) or [r.get('native_frame') for r in action_rows]!=original_frames:
                raise ValueError('Device action original frame join differs')
            if any(r.get('device_id')!='620' or r.get('device_type')!='206' or
                   r.get('device_road_id')!=2 or isinstance(r.get('ego_speed_mps'),bool) or
                   not isinstance(r.get('ego_speed_mps'),(int,float)) or not math.isfinite(r['ego_speed_mps'])
                   for r in action_rows):
                raise ValueError('Device and ego Native readback differs')
            action_frames={index for index,r in enumerate(action_rows) if r.get('ego_brake_applied') is True}
            if action_frames!=set(packet.get('ego_action_frames',[])):
                raise ValueError('Device ego action source does not match exception context')
            if not action_frames or not all(index>0 and action_rows[index]['ego_speed_mps']<action_rows[index-1]['ego_speed_mps']
                                            for index in action_frames):
                raise ValueError('Device ego action has no measured deceleration')
        if branch == 'police_or_device_direction':
            video=path.parent/'parking.mkv'
            if not video.is_file() or hashlib.sha256(video.read_bytes()).hexdigest() != packet.get('original_pixel_sha256'):
                raise ValueError('Direction original video hash differs')
        if branch == 'necessary_traffic_conflict':
            actor_source=path.parent/'other_actor_history.jsonl'
            ego_source=path.parent/'ego_response_history.jsonl'
            if not actor_source.is_file():
                raise ValueError('Missing required source: other_actor_history.jsonl')
            if not ego_source.is_file():
                raise ValueError('Missing required source: ego_response_history.jsonl')
            actor_rows=[json.loads(line) for line in actor_source.read_text().splitlines() if line.strip()]
            ego_rows=[json.loads(line) for line in ego_source.read_text().splitlines() if line.strip()]
            if len(actor_rows)!=len(original_frames) or [r.get('native_frame') for r in actor_rows]!=original_frames:
                raise ValueError('Other actor original frame join differs')
            if len(ego_rows)!=len(original_frames) or [r.get('native_frame') for r in ego_rows]!=original_frames:
                raise ValueError('Ego response original frame join differs')
            active={index for index,r in enumerate(actor_rows) if r.get('conflict_occupancy') is True}
            if not active.intersection(packet.get('other_actor_frames',[])):
                raise ValueError('Conflict source does not match original actor history')
            braking={index for index,r in enumerate(ego_rows) if r.get('response_onset') is True}
            if braking != set(packet.get('ego_brake_frames',[])) or any(
                ego_rows[index].get('conflict_brake_override') is not True or
                ego_rows[index].get('brake_applied') is not True for index in braking):
                raise ValueError('Ego conflict-brake onset does not match exception context')
            for index,r in enumerate(ego_rows):
                expected_onset=(r.get('conflict_brake_override') is True and
                                (index==0 or ego_rows[index-1].get('conflict_brake_override') is not True))
                if r.get('response_onset') is not expected_onset:
                    raise ValueError('Ego conflict-brake onset differs from override history')
            if not braking or not any(any(abs(a-b)<=1 for a in active) for b in braking):
                raise ValueError('Ego brake does not overlap the source conflict window')
            for index in braking:
                if index==0 or not isinstance(ego_rows[index]['speed_mps'],(int,float)) or not isinstance(ego_rows[index-1]['speed_mps'],(int,float)) or not math.isfinite(ego_rows[index]['speed_mps']) or not math.isfinite(ego_rows[index-1]['speed_mps']) or ego_rows[index]['speed_mps']>=ego_rows[index-1]['speed_mps']:
                    raise ValueError('Ego brake has no measured deceleration')
        source = inspect_present(path, digest, branch)
        return {'source': source, 'requested_polarity': polarity,
                'source_sha256': digest, 'physical_observation_claimed': False}
    if packet.get('observed_exception_source_ids') != []:
        raise ValueError('Absent exception inventory contains a source')
    return {'branch': branch, 'requested_polarity': polarity,
            'source_sha256': digest, 'inventory_frames': len(original_frames),
            'applicability': 'requires_independent_review',
            'physical_observation_claimed': False, 'legal_exception_verdict': None}

"""Source-bound exception evidence gates; no legal exception verdict."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

NEEDED={
    "necessary_traffic_conflict": ("other_actor_frames","ego_brake_frames","intersection_boundary_source"),
    "compliance_with_law": ("cited_law_id","cited_law_text_sha256","ego_action_frames"),
    "police_or_device_direction": ("original_pixel_sha256","direction_source_id","direction_frame","ego_action_frames"),
}


def inspect(source:Path,expected_sha256:str,branch:str)->dict:
    if branch not in NEEDED:raise ValueError("Unknown statutory exception")
    if hashlib.sha256(source.read_bytes()).hexdigest()!=expected_sha256:
        raise ValueError("Exception evidence source hash differs")
    packet=json.loads(source.read_text())
    if packet.get("source_kind")!="native_context_schema" or packet.get("branch")!=branch:
        raise ValueError("Exception evidence identity differs")
    missing=[key for key in NEEDED[branch] if not packet.get(key)]
    if missing:raise ValueError("Missing original exception source: "+missing[0])
    if branch=="necessary_traffic_conflict":
        actors=packet["other_actor_frames"];brakes=packet["ego_brake_frames"]
        if (not isinstance(actors,list) or not isinstance(brakes,list) or
            any(type(i)!=int or i<0 or i>=480 for i in actors+brakes) or
            not set(actors)&set(brakes)):
            raise ValueError("Conflict and ego response are not time joined")
    elif branch=="compliance_with_law":
        if (len(packet["cited_law_text_sha256"])!=64 or
            not isinstance(packet["ego_action_frames"],list)):
            raise ValueError("Cited law or observed action source differs")
    else:
        if (len(packet["original_pixel_sha256"])!=64 or
            type(packet["direction_frame"])!=int or
            packet["direction_frame"] not in packet["ego_action_frames"]):
            raise ValueError("Direction pixels and actor action are not joined")
    return {"branch":branch,"source_sha256":expected_sha256,
            "source_packet_complete":True,"applicability":"requires_independent_review",
            "physical_observation_claimed":False,"legal_exception_verdict":None}
